  'settings.connections.type': 'Тип',
  'settings.connections.typeHint': '«Нет» и «Прямое» — не одна и та же строка. «Нет» бездействует: она не называет никакого соединения и никогда не используется, поэтому живёт лишь до тех пор, пока вы её не заполните. «Прямое» — настоящий выбор: выходить через собственный канал этой машины и намеренно обходить любой прокси для перечисленных ниже хостов, чем NAS и выводится из-под общего для всего приложения прокси. Строка, чей фильтр совпал с хостом, бьёт строку без фильтра, поэтому прямая строка с фильтром всегда выигрывает у прокси, который ловит всё.',
