  'settings.rules.flavour.packagizer': 'Packagizer',
  'settings.rules.flavour.filter': 'Фильтр ссылок',
  'settings.rules.flavourLabel': 'Какой список правил',
  'settings.rules.setupTitle': 'Набор правил',
  'settings.rules.packagizerHint': 'Проходит по каждой ссылке в момент подготовки и переписывает то, что может: пакет, папку, комментарий, приоритет, соединения, автораспаковку. Каждое подошедшее правило вносит своё, а в одном поле побеждает более позднее.',
  'settings.rules.filterHint': 'Решает, попадёт ли ссылка в сборщик вообще. Отклонённая ссылка не удаляется: она придерживается вместе с правилом и причиной, которые её остановили, чтобы ничто никогда не исчезало без объяснения.',
  'settings.rules.setOn': 'Этот список применяется',
  'settings.rules.setOff': 'Этот список выключен',
  'settings.rules.setSwitchHint': 'Главный переключатель всего списка. Выключен — ни одно правило ниже не работает, но все они по-прежнему редактируются и проверяются вхолостую, потому что список невозможно починить, если выключение заодно прячет, что с ним не так.',
  'settings.rules.stopAfterMatch': 'Останавливаться на первом подошедшем правиле',
  'settings.rules.stopHint': 'Выключено — каждое подошедшее правило вносит своё, и в одном поле побеждает более позднее: этого хочет Packagizer. Включено — разбор заканчивается на первом совпадении: этого обычно хочет фильтр, и тогда «принять» над широким «отклонить» действительно защищает ссылку.',
  'settings.rules.listTitle': 'Правила в порядке выполнения',
