  'settings.rules.name': 'Название',
  'settings.rules.namePlaceholder': 'Для чего это правило',
  'settings.rules.nameHint': 'Показывается только вам — в этом списке, у проблемы и у причины, по которой ссылку придержали. Правило без названия зовётся по своей позиции, а она меняется при перестановке списка.',
  'settings.rules.sectionIf': 'Если всё это верно',
  'settings.rules.ifHint': 'Должно выполняться каждое условие. «Или-или» пишется двумя правилами, и список остаётся читаемым сверху вниз. Правило БЕЗ условий подходит к любой ссылке — так пишут папку для всего остального или общий отказ в конце.',
  'settings.rules.fieldPicker': 'На что смотреть',
  'settings.rules.opPicker': 'Как сравнивать',
  'settings.rules.sectionThen': 'Тогда',
  'settings.rules.thenHintPackagizer': 'Пустое поле значит «не трогай», а не «очисти»: правило, задающее только папку, не должно стирать имя пакета, выбранное более ранним правилом.',
  'settings.rules.thenHintFilter': 'Правило, которое отклоняет, придерживает ссылку вместе со своей причиной. Правило, которое принимает, тоже полезно: поставленное над широким отказом при включённой остановке на первом совпадении, оно пропускает ровно одного хостера.',
  'settings.rules.addCondition': 'Добавить условие',
