  'settings.rules.noUpperBound': 'без верхней границы',
  'settings.rules.sizeHint': 'Просто число — это байты. Единица тоже понимается — 700 MB, 1.5 GiB — и обе читаются по основанию 1024, как и любой размер, который выводит остальное приложение.',
  'settings.rules.badSize': 'Это не размер.',
  'settings.rules.pattern': 'Шаблон',
  'settings.rules.patternHint': 'Регулярное выражение Go, без якорей, и единственный оператор, который НЕ игнорирует регистр — поставьте (?i) в начало, если хотите. Нечитаемый шаблон отклоняется с указанием причины, а не молча перестаёт совпадать со всем.',
  'settings.rules.category': 'Тип файла',
  'settings.rules.categoryCustom': 'Свой шаблон',
  'settings.rules.categoryHint': 'Быстрый выбор, который подставляет шаблон для целого семейства расширений. Сохраняется он как обычный шаблон, так что можно выбрать и потом отредактировать — после чего здесь снова будет «свой шаблон», потому что он больше не описывает правило.',
  'settings.rules.categoryExtensions': 'Включает: {list}',
  'settings.rules.unchanged': 'Без изменений',
  'settings.rules.yes': 'Вкл',
  'settings.rules.no': 'Выкл',
  'settings.rules.reject': 'Отклонить ссылку',
  'settings.rules.accept': 'Принять ссылку',
  'settings.rules.priorityHint': 'Выше — раньше. Диапазон тот же, что принимает сама очередь, поэтому правило не выдаст задаче приоритет, который вам нечем отменить. Оставьте пустым, чтобы ничего не менять.',
  'settings.rules.chunksHint': 'Сколькими соединениями качается этот один файл. Оставьте пустым, чтобы использовать общую настройку. Больше нескольких штук ничего не даёт у хостера с ограничением на файл и надёжно приводит к пометке учётной записи.',
  'settings.rules.emptyMeansUnchanged': 'пусто = без изменений',

  'settings.rules.variables': 'Переменные',
  'settings.rules.variablesTitle': 'Вставить переменную',
