  'settings.rules.var.source': 'N-й сегмент пути адреса страницы-источника, считая с 1: для https://site.org/tv/s01/list.html 1 — это tv, а 2 — s01. НЕ то, что понимает под этим тегом JDownloader — см. примечание ниже.',
  'settings.rules.var.match': 'Группа захвата N шаблона «совпадает с шаблоном» этого правила по полю FIELD. Это <jd:source:N> из JDownloader под именем, которое говорит, какой шаблон он читает. Правило без подходящего шаблона на этом поле отклоняется при сохранении, а не создаёт молча папку с именем <jd:match:url:1>.',
  'settings.rules.var.append': 'Ничего при первом появлении этого значения, дальше _2, _3 и так далее',
  'settings.rules.sourceDivergence': 'Копируете шаблон из конфигурации JDownloader? Здесь <jd:source:N> значит другое — сегмент пути исходного адреса, а не группу захвата. Смысл JD записывается как <jd:match:FIELD:N>. Совпадают они достаточно часто, чтобы это было опасно, так что скопированный шаблон стоит прогнать вхолостую ниже, прежде чем сохранять.',

  'settings.rules.testTitle': 'Проверить на ссылке',
  'settings.rules.testHint': 'Здесь ничего не скачивается, не хранится и не сохраняется. Список в том виде, в каком он на этой странице, прогоняется по этим образцам тем же кодом, что работает при приёме ссылок.',
