  'settings.reconnect.checkTitle': 'Проверка адреса',
  'settings.reconnect.checkUrl': 'URL для проверки IP',
  'settings.reconnect.checkUrlHint': 'Запрашивается до запуска способа и ещё раз после; прогон считается выполненным, как только выданный там адрес изменится. Значения по умолчанию нет намеренно: менеджер загрузок, который вы держите у себя, не должен начинать сообщать ваш адрес службе, которую вы никогда не выбирали. Выдаваться должен адрес, который видит интернет, потому что страница, возвращающая адрес из вашей собственной сети, не отличит переподключение от бездействия.',
  'settings.reconnect.checkPresets': 'Известные службы',
