  'settings.reconnect.policy': 'Когда это случается само',
  'settings.reconnect.policyHint': 'Автоматические переподключения запускаются ровно в одном месте, и это не данная страница. Одно из них стартует, когда сам движок загрузки просит о новой попытке после паузы: так хостер сообщает, что лимит привязан к этому адресу. Оно никогда не выполняется при остановленной очереди, потому что перезагрузка роутера обрывает ещё идущие загрузки. Оно никогда не выполняется, пока переподключение настроено не до конца. Одновременно идёт только одно: второй запрос ждёт вердикта первого, вместо того чтобы драться с ним за роутер. А если адрес не меняется, ничего не ускоряется и обычная пауза между попытками доигрывается до конца.',

