  'settings.chunks': 'Соединений на загрузку (0 = автоматически)',
  'settings.chunksHint': 'Сколько соединений открывает одна загрузка, когда ничего более конкретного не действует. Правило или отдельная загрузка может назвать своё число и перебивает это. Хостер, который терпит меньше, всё равно получит меньше: ограничение хостера может число только снизить, но не поднять. При 0 решает приложение. Больше нескольких соединений ничего не даёт у хостера с ограничением на файл и надёжно приводит к пометке учётной записи.',
  'task.chunks': 'Соединения (0 = общая настройка)',
  'task.chunksHint': 'Сколько соединений открывает эта одна загрузка. Она перебивает общую настройку и любое правило, которое её задало, но никогда не хостера: хостер, который терпит меньше, всё равно получит меньше. При 0 исключение снимается и число снова решается не здесь.',
  'columns.connection': 'Соединение',

  'props.title': 'Свойства',
