  'props.mixedHint': 'Эти строки расходятся, поэтому поле пустое. Если его не трогать, ничего не изменится; впишите что-нибудь, и каждая выбранная строка получит вписанное.',
  'props.name': 'Имя',
  'props.nameHint': 'Одно имя файла, никогда не путь: всё, что расписывает папки, обрезается до одного имени. Завершённая загрузка переименовывается и на диске, чтобы список и папка не расходились. Идущая сохраняет файл, открытый её движком, и берёт новое имя, когда закончит. Ещё не начатая берёт его сразу. Имя принадлежит одному файлу, поэтому это поле предлагается только для одной строки.',
  'props.comment': 'Комментарий',
  'props.commentHint': 'Твоя собственная заметка об этой ссылке. Она сохраняется и показывается в списке; ничто в приложении по ней не действует.',
  'props.priority': 'Приоритет',
  'props.priorityHint': 'Более высокий идёт первым. Он переставляет то, что ещё ждёт; уже идущая загрузка обратно в очередь не отправляется.',
  'props.autoExtract': 'Распаковывать архивы',
