  'accounts.debrid.emptyHint': 'Добавь ключ одного из поддерживаемых debrid-сервисов, чтобы ссылки хостеров открывались автоматически.',
  'accounts.debrid.title': 'Аккаунты debrid',
  'accounts.debrid.hint': 'Debrid-сервис — это один платный аккаунт, который открывает сразу много файлохостингов. KnightLoader отправляет ему ссылку и качает прямую ссылку, которую получает в ответ: полная скорость, без ожидания и без капчи. Это рекомендуемый путь, потому что иначе нужен отдельный премиум-аккаунт на каждом хостинге.',
