  'accounts.routing.priorityTitle': 'Порядок приоритета',
  'accounts.routing.priorityHint': 'Какую службу спрашивают первой, когда одну и ту же ссылку может взять не одна. Перетаскивайте, чтобы изменить порядок.\n\nЗдесь всё, что может забрать ссылку, а не только аккаунты debrid: TorBox, AllDebrid и подобные, JDownloader для сотен хостеров, yt-dlp для видеосайтов и обычная прямая загрузка для обычной ссылки. Поэтому TorBox и yt-dlp стоят в одном списке - и то и другое дороги, по которым может пойти ссылка.\n\nПорядок решает только между службами, которые действительно могут взять данную ссылку. Перетаскивание yt-dlp наверх не отправит туда ссылку с файлохостинга.',
