  'settings.access.relay.title': 'Ретранслятор проекта',
  'settings.access.relay.body': 'Реле — это посредник, благодаря которому все ваши экземпляры доступны за пределами домашней сети, то есть откуда угодно. Это реле проект предоставляет бесплатно.',
  'settings.access.relay.use': 'Использовать ретранслятор проекта',
  'settings.access.relay.leadProject': 'Работает без настройки. Всё, что твои экземпляры говорят друг другу, зашифровано, и ключ есть только у тебя.',
  'settings.access.relay.address': 'Адрес',
  'settings.access.relay.seesButton': 'Что он видит?',
  'settings.access.relay.seesTip': 'Реле не видит: ваши ссылки, загрузки, файлы и токен доступа.\n\nРеле видит: IP-адреса ваших экземпляров и когда они что-то отправляют.\n\nЭто шифрованием не спрятать. Если смущает, поднимите собственное реле.',
  'settings.access.relay.none': 'Без ретранслятора',
  'settings.access.relay.noneHint': 'Реле не активно. В одной сети, то есть в вашей домашней, экземпляры по-прежнему находят друг друга сами. Между разными сетями они не связываются, поэтому удалённого доступа нет.',
  'settings.access.relay.own': 'Свой ретранслятор',
  'settings.access.relay.project': 'Ретранслятор проекта',
  'settings.access.relay.whichHint': 'Идёт через {address}',
  'settings.access.relay.savedProject': 'Ретранслятор проекта активен',
  'settings.access.relay.savedOwn': 'Твой ретранслятор активен',
  'settings.access.relay.savedOff': 'Ретранслятор выключен',
  'settings.access.ownRelay.title': 'Свой ретранслятор',
  'settings.access.ownRelay.body': 'Запустите собственное реле вместо проектного.',
  'settings.access.ownRelay.use': 'Использовать свой ретранслятор',
  'settings.access.ownRelay.lead': 'Два пути: этот экземпляр берёт ретранслятор на себя, или ты вводишь адрес.',
  'settings.access.ownRelay.serveLabel': 'Использовать этот экземпляр как реле',
  'settings.access.ownRelay.serveHint': 'Работает только если этот экземпляр доступен извне, например через Nginx Proxy Manager и собственный домен.',
  'settings.access.ownRelay.serveClients': 'Сейчас подключено: {count}.',
  'settings.access.ownRelay.addressLabel': 'Адрес',
  'settings.access.ownRelay.addressPlaceholder': 'напр. https://relay.mydomain.tld',
  'settings.access.ownRelay.save': 'Сохранить',
  'settings.access.ownRelay.everyInstance': 'Этот адрес относится только к этому экземпляру. Введи его на каждом.',
  'settings.access.ownRelay.containerLabel': 'Отдельным контейнером',
  'settings.access.ownRelay.containerHint': 'Если ни один ваш экземпляр не доступен извне, реле должно стоять в другом месте: на вашем сервере или на небольшом VPS. Установите контейнер из Unraid Community Applications или командой ниже.\n\nКонтейнеру не нужна настройка: запустите, впишите его адрес выше, готово. Он ничего не хранит, так что и резервировать нечего.',
  'settings.access.tokens.title': 'Токены API',
  'settings.access.tokens.intro':
    'Именованные учётные данные для скрипта, расширения браузера или телефона. Каждый можно отозвать по отдельности, не меняя общий пароль, которым пользуются остальные клиенты.',
  'settings.access.tokens.empty': 'Токены пока не выданы.',
  'settings.access.tokens.new': 'Новый токен',
  'settings.access.tokens.namePlaceholder': 'напр. мой телефон',
