  'settings.access.tokens.create': 'Создать',
  'settings.access.tokens.creating': 'Создание…',
  'settings.access.tokens.created': 'Создан',
  'settings.access.tokens.lastUsed': 'Последнее использование',
  'settings.access.tokens.neverUsed': 'никогда',
  'settings.access.tokens.revoke': 'Отозвать',
  'settings.access.tokens.secretTitle': 'Скопируйте этот токен сейчас',
  'settings.access.tokens.secretWarning':
    'Этот токен показывается только один раз. Он хранится на этом экземпляре в виде одностороннего хэша - если он потерян, прочитать его снова невозможно, можно только отозвать его и создать новый.',
  'settings.access.tokens.copy': 'Копировать',
  'settings.access.tokens.copied': 'Скопировано',
  'settings.access.tokens.done': 'Готово',
  'settings.access.tokens.howToUse': 'Отправляйте его как заголовок: Authorization: Bearer <token>',
  'settings.access.tokens.createFailed': 'Не удалось создать токен: {error}',
  'settings.access.identity.title': 'Идентичность этого экземпляра',
  'settings.access.identity.nameLabel': 'Имя',
  'settings.access.identity.namePlaceholder': 'например, Домашний сервер',
  'settings.access.identity.nameHint': 'Предлагается первым при сопряжении и в QR-коде ниже, вместо того, как эту машину случайно называет операционная система или среда выполнения контейнера. Необязательно - оставьте пустым, чтобы продолжать использовать то имя.',
  'settings.access.identity.domainsLabel': 'Известные домены',
  'settings.access.identity.domainsHint': 'Запоминается автоматически, как только через него действительно приходит запрос, поэтому он остаётся здесь в списке, даже если последующие запросы приходят через LAN IP. Добавьте один вручную для домена, который уже настроен, но через который ещё не заходили - один полный адрес на строку, напр. https://kl.example.com.',
  'settings.access.cardTitle': 'Связь экземпляров и удалённый доступ',
  'settings.access.phrase.body': 'Одна фраза связывает все ваши экземпляры KnightLoader. Создайте её здесь и вставьте в остальные - без учётной записи, без входа, без настроек.',
  'settings.access.phrase.noPasswordWarning': 'У этого экземпляра нет пароля. Фраза открывает каждый экземпляр, который вы с ней свяжете, поэтому тот, кто прочитает её здесь, доберётся до всех, а не только до этого. Лучше сначала задайте пароль выше.',
  'settings.access.phrase.activate': 'Создать фразу',
  'settings.access.phrase.howLead': 'Двенадцать слов, и всё. Вот что делать и что при этом происходит:',
  'settings.access.phrase.howStep1': 'На этом экземпляре нажмите «{button}». Появятся двенадцать слов.',
  'settings.access.phrase.howStep2': 'Откройте KnightLoader на другой машине, зайдите на эту же страницу, нажмите «{button}» и введите двенадцать слов.',
  'settings.access.phrase.howStep3': 'Готово! Каждый экземпляр теперь виден у другого в разделе «Экземпляры», и любым можно управлять из любого. При включённом реле ваши экземпляры доступны и снаружи вашей сети.',
  'settings.access.phrase.howWhat': 'Слова — это секрет, а не адрес. Каждый экземпляр выводит из них два ключа: один чтобы найти остальных, другой чтобы шифровать.\n\nЧтобы найти друг друга, каждый экземпляр сам звонит в одну и ту же точку встречи в интернете. Кто предъявляет тот же ключ, того соединяют. Поэтому ни один из ваших экземпляров не обязан быть доступным извне.\n\nТочка встречи не может читать. Она никогда не видит ваши слова, а всё, что через неё проходит, зашифровано вторым ключом.',
  'settings.access.phrase.statusDisconnected': 'Не подключено',
  'settings.access.phrase.statusHintProject': 'Подключено к реле проекта. Удалённый доступ настроен.',
  'settings.access.phrase.statusHintOwn': 'Подключено к вашему реле. Удалённый доступ настроен.',
  'settings.access.phrase.statusHintOff': 'Реле не активно. Ваши экземпляры доступны только в локальной сети.',
  'settings.access.phrase.statusHintLost': 'Нет связи с реле. KnightLoader продолжает попытки. До тех пор экземпляры видят друг друга только в локальной сети.',
  'settings.access.phrase.statusConnected': 'Подключено',
