  'settings.nav.browsertools': 'Браузер и приложение',
  'settings.browsertools.bookmarkletStep1': 'Перетащи кнопку ниже на панель закладок браузера - она сохраняется как любая другая закладка, ничего не устанавливается.',
  'settings.browsertools.bookmarkletStep2': 'На любой странице щёлкни по ней (сначала выдели текст, если нужен только он). Откроется небольшая вкладка KnightLoader со ссылкой на эту страницу или выделенным текстом, уже заполненная - проверь и добавь как загрузку оттуда.',
