  'settings.resolvers.moduleUnavailableHint': 'Всё ниже всё равно сохраняется и вступает в силу, как только yt-dlp станет доступен - при редактировании сейчас ничего не потеряется.',
  'settings.resolvers.intro': 'Настройки backend-а yt-dlp, который получает медиа- и стриминговые сайты, поддерживаемые самим yt-dlp. Какая служба вообще обрабатывает ссылку - yt-dlp, аккаунт debrid, headless-сайдкар JD - решается порядком маршрутизации на странице «Аккаунты»; здесь описано только то, что делает yt-dlp, когда ссылка уже направлена к нему.',
