  'settings.torrents.title': 'Торренты',
  'settings.torrents.subtitle': 'Целевой рейтинг раздачи, лимиты передачи, проброс порта и DHT/PEX для magnet-ссылок и файлов .torrent.',
  'settings.torrents.seedingTitle': 'Раздача',
  'settings.torrents.seedRatio': 'Целевой рейтинг раздачи',
  'settings.torrents.seedRatioHint': 'Продолжает раздавать завершённый торрент, пока в рой не будет возвращено столько же, сколько составляет его собственный размер. 0 = без цели по рейтингу.',
  'settings.torrents.seedDuration': 'Целевая длительность раздачи',
  'settings.torrents.seedDurationHint': 'Продолжает раздавать завершённый торрент столько времени после завершения. 0 = без ограничения по времени. Раздача останавливается по первой из двух целей выше, которая будет достигнута.',
  'settings.torrents.seedDurationUnit': 'часов',
  'settings.torrents.transferTitle': 'Лимит передачи',
  'settings.torrents.uploadLimit': 'Лимит отдачи',
  'settings.torrents.uploadLimitHint': 'Ограничивает скорость, с которой торрент отдаёт данные в рой во время раздачи. 0 = без ограничений.',
  'settings.torrents.uploadLimitUnit': 'КиБ/с',
  'settings.torrents.portTitle': 'Порт и проброс',
  'settings.torrents.port': 'Порт',
  'settings.torrents.portHint': 'Порт, на котором этот экземпляр принимает соединения роя. 0 позволяет торрент-движку выбрать порт самому.',
  'settings.torrents.portMapHint': 'Просит роутер пробросить указанный выше порт на эту машину по UPnP, чтобы пиры за другим роутером всё равно могли до него достучаться. Не каждый роутер это поддерживает, а некоторые принимают запрос, хотя реально ничего не работает.',
  'settings.torrents.portMapButton': 'Попробовать проброс UPnP',
  'settings.torrents.portMapping': 'Опрос роутера…',
  'settings.torrents.portMapNeedsPort': 'Сначала укажите порт выше, прежде чем пробрасывать его - при 0 роутеру некуда пробрасывать.',
  'settings.torrents.portMapConfirmed': 'Подтверждено: порт {port} проброшен, доступность проверена.',
  'settings.torrents.portMapUnconfirmed': 'Роутер принял запрос, но подтвердить, что проброс реально работает, не удалось. Некоторые роутеры делают это молча - попробуйте проверить доступность извне сети.',
  'settings.torrents.portMapFailed': 'Не удалось пробросить порт: {error}',
  'settings.torrents.portMapUnavailable': 'Эта сборка пока не поддерживает проброс портов.',
  'settings.torrents.networkTitle': 'Поиск пиров',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Находит пиров без участия трекера, используя другие BitTorrent-клиенты как распределённый справочник.',
  'settings.torrents.pex': 'Обмен пирами (PEX)',
  'settings.torrents.pexHint': 'Обменивается известными пирами с уже подключёнными, чтобы рой с малым числом пиров находился быстрее.',
  'settings.torrents.privateNote': 'Приватный торрент автоматически отключает оба варианта, как только становятся известны его метаданные, независимо от настройки здесь - сразу же для загруженного файла .torrent или как только собственные метаданные magnet-ссылки приходят из роя. Большинство приватных трекеров банят аккаунты, использующие любой из них.',
  'settings.torrents.engineNote': 'Целевой рейтинг раздачи, целевая длительность раздачи и порт теперь действуют на каждый торрент, который запускает этот движок - порт, впрочем, только для самого первого торрента с последнего перезапуска этого экземпляра, потому что собственный торрент-клиент движка собирается только один раз и больше никогда не пересобирается; более позднее сохранение всё равно сохраняется корректно и вступает в силу начиная со следующего перезапуска. Лимит отдачи по-прежнему только сохраняется и проверяется - движку пока некуда донести его до активной загрузки. DHT и PEX ниже в такой же ситуации для обычного (неприватного) торрента: собственное значение по умолчанию этого экземпляра тоже пока не доходит до активной загрузки, поэтому торрент по-прежнему раздаётся с обоими включёнными независимо от настройки здесь - приватный торрент - совсем другой случай, см. примечание ниже. Кнопка проброса ниже всё же делает кое-что реальное: она честно просит роутер пробросить введённый выше номер порта, независимо от того, слушает ли его сейчас какой-либо торрент.',
  'torrent.staging': 'Добавление…',
