  'onboarding.back': 'Назад',
  'onboarding.next': 'Далее',
  'onboarding.finish': 'Начать пользоваться KnightLoader',
  'onboarding.welcome.title': 'Добро пожаловать в KnightLoader',
  'onboarding.welcome.body': 'KnightLoader — это самостоятельно размещаемый менеджер загрузок: вставьте или перетащите ссылку, и её заберёт тот бэкенд, который действительно её обрабатывает - встроенный движок для обычных файловых ссылок, yt-dlp для медиастраниц, дебрид-сервис для хостеров, за которые вы уже платите, или headless JDownloader для всего остального. Этот короткий обзор охватывает единственную настройку, которую стоит проверить перед началом.',
  'onboarding.welcome.langLabel': 'Язык интерфейса',
  'onboarding.folder.title': 'Куда должны попадать файлы?',
  'onboarding.folder.body': 'Это папка, в которую записываются завершённые загрузки. Введите путь или просмотрите сервер, чтобы выбрать его - вы всегда можете снова изменить это на странице общих настроек.',
  'onboarding.accounts.title': 'Премиум-хостеры, когда бы вы ни захотели',
  'onboarding.accounts.body': 'Очередь работает вообще без учётной записи. Когда захотите полную скорость у хостера или дебрид-сервиса, за который уже платите, добавьте его логин в разделе «Аккаунты» - здесь сейчас ничего настраивать не нужно.',
  'onboarding.accounts.link': 'Открыть «Аккаунты»',
  'onboarding.finished.title': 'Всё готово',
  'onboarding.finished.body': 'На этом обзор заканчивается. Страница «Справка» в настройках содержит полное описание всего остального, что умеет эта версия, а у большинства элементов управления есть собственное объяснение за значком (i).',

