  'settings.downloads.collectorTitle': 'Сборщик',
  'settings.downloads.diskTitle': 'Место на диске',
  'settings.downloads.diskHint': 'Три числа, которые придерживают загрузки до того, как диск заполнится, а не после. Все три означают свободные байты на том томе, куда сейчас пишется загрузка, поэтому рабочая папка на другом диске меряется по нему. Ноль отключает соответствующее число. Учтите, чего это не может: не у каждой системы можно спросить, сколько места свободно, и там, где ответа нет, ничего и не придерживается, потому что охрана, блокирующая при незнании, остановила бы совершенно здоровую машину.',
