  'settings.feeds.seededHint': 'Первый опрос новой подписки записывает всё, что лента несёт в этот момент, и не добавляет из этого ничего, чтобы к вам разом не свалился весь архив издателя. Добавляется только то, что появится после этого.',
  'settings.feeds.remembered': 'Запомнено записей: {n}',
  'settings.feeds.rememberedHint': 'Сколько записей эта подписка узнаёт снова, чтобы они не добавились во второй раз, пока лента их ещё отдаёт. Не больше 500 на подписку; первыми выпадают самые старые, и запись, которая ещё стоит в ленте, среди них не оказывается никогда.',
  'settings.feeds.test': 'Проверить',
  'settings.feeds.testBusy': 'Опрашивается…',
