  'settings.headerProfiles.title': 'Профили заголовков',
  'settings.headerProfiles.hint': 'Некоторые сайты отдают файл только вошедшему браузеру или только тогда, когда запрос пришёл с одной из их собственных страниц. Профиль хранит заголовки ровно для одного сайта, зашифрованными так же, как ваши ключи от аккаунтов, и KnightLoader отправляет их с каждой загрузкой с этого сайта.',
  'settings.headerProfiles.empty': 'Профилей заголовков пока нет.',
  'settings.headerProfiles.emptyHint': 'Профиль стоит завести, как только загрузка работает лишь тогда, когда вы вошли в браузере.',
