  'settings.rules.action.category': 'Категория',
  'settings.rules.action.categoryHint': 'Раскладывает подошедшие ссылки в один из ящиков со страницы «Категории», а тот приносит с собой собственную папку, место в очереди, переключатель распаковки и правило для файла, который уже есть. Оставьте «Без изменений», и ни одно правило об этом ничего не говорит, а ссылка остаётся неразложенной. Если это правило называет ещё и папку загрузок, побеждает она, а всё остальное по-прежнему даёт ящик. Назвать удалённый ящик при сохранении не дадут, потому что правило, указывающее на ящик, которого нет, на каждой подошедшей ссылке не делает вообще ничего, и молча.',
  'settings.rules.action.categoryNone': 'Категорий пока нет. Сначала заведите одну на странице «Категории», иначе это правило раскладывало бы ссылки в ящик, которого не существует.',
  'settings.rules.action.categoryMissing': '{id} (удалена)',
