  'detail.noPackage': 'Без пакета',
  'detail.onDisk': 'Сейчас на диске',
  'detail.onDiskHint': 'Сколько файл занимает на диске в эту секунду; значение спрашивается у сервера, а не считается здесь. Идущая загрузка растёт между двумя взглядами, и это не тот размер, который назвал хостер.',
  'detail.mirrorOf': 'Запасная копия для',
  'detail.times': 'Отметки времени',
  'detail.timesHint': 'Когда эта ссылка пришла, когда она в последний раз менялась и когда всё закончилось. Времени начала передачи здесь нет: приложение его нигде не записывает, а значение, угаданное по трём остальным, было бы числом, по которому люди принимают решения.',
  'detail.nextTry': 'Следующая попытка',
  'detail.stalledSince': 'Стоит на месте с',
  'detail.retries': 'Повторных попыток',
  'detail.retriesHint': 'Сколько раз эту загрузку пробовали снова после ошибки. Счётчик обнуляется в тот момент, когда загрузка завершается, поэтому у готовой строки стоит ноль, даже если понадобилось четыре захода. Сколько попыток осталось, здесь не показано: предел зависит от причины и от хостера, и эта страница его не вычислит.',
  'detail.stallRestarts': 'Перезапусков после остановки',
