  'detail.messageHint': 'Фраза от того, кто пытался это забрать, дословно и без перевода. Это текущая ошибка и ничего больше: перезапуск её стирает, а прежние нигде не сохраняются.',
  'detail.heldBack': 'Что задерживает',
  'detail.doing': 'Сейчас делает',
  'detail.filtered': 'Придержано фильтром ссылок',
  'detail.gaveUp': 'Больше не пробует',
  'detail.gaveUpHint': 'Здесь остановились намеренно, а не потому, что кончились попытки: капча, заполненный диск или правило, которое для этого хостера говорит «никогда». Увеличить число повторов тут ничего не меняет. Сама пометка в базу не записывается, поэтому после перезапуска её нет, хотя причина никуда не делась.',
  'detail.rules': 'Правила, которые это сформировали',
  'detail.rulesHint': 'Правила, сработавшие на этой ссылке при подготовке, в том порядке, в каком они сработали. Они хранятся по имени, поэтому переименованное с тех пор правило больше не находится, а правило, у которого имени и не было, хранится по той позиции, которая была у него тогда. Щелчок открывает правило в редакторе правил.',
  'detail.openRule': 'Открыть в редакторе правил',
  'detail.noRules': 'Ни одно правило эту ссылку не трогало.',
  'detail.player': 'Воспроизведение',
  'detail.play': 'Воспроизвести здесь',
  'detail.playHint': 'Воспроизводит файл прямо с этого экземпляра, не скачивая его второй раз. Пока вы не нажали воспроизведение, ничего не запрашивается, и файл остаётся там, где лежит.',
  'detail.playPartial': 'Эта загрузка не завершена. Воспроизвести можно только ту часть, которая уже лежит на диске, перемотать дальше не получится, а некоторые файлы не играют вообще ничего, пока не придёт последний байт.',
  'detail.playUnsupported': 'Этот браузер не умеет воспроизводить такой файл. Откройте или сохраните его через меню по правому щелчку.',
