  'settings.rules.notFound': 'Здесь нет правила с именем «{name}». Его переименовали или удалили уже после того, как добавили ссылку, которая его называет.',
  'notifications.title': 'Уведомления',
  'notifications.titleHint': 'Решите для каждого события, показывать ли его пузырьком в приложении, уведомлением вашей операционной системы или не показывать вовсе. Системное уведомление доходит до вас, только пока открыта вкладка KnightLoader, а тихий режим ниже действует вдобавок к этому.',
  'notifications.channel.app': 'В приложении',
  'notifications.channel.system': 'Системное уведомление',
