  'notifications.event.downloadDoneHint': 'Каждая загрузка, дошедшая до конца, сообщает об этом. Двести файлов в очереди, это двести уведомлений, поэтому подумайте дважды, прежде чем отправлять их в систему.',
  'notifications.event.downloadFailed': 'Загрузка не удалась',
  'notifications.event.downloadFailedHint': 'Загрузка, которая сдалась. Тихий режим её не скрывает никогда.',
  'notifications.event.extractionDone': 'Распаковка завершена',
  'notifications.event.extractionDoneHint': 'Архив, который распаковался до конца. Раньше об этом нигде не сообщалось, поэтому изначально стоит «Ничего не показывать».',
  'notifications.event.extractionFailed': 'Распаковка не удалась',
  'notifications.event.extractionFailedHint': 'Архив, который остановился, не закончив. Обычная причина, это отсутствующий пароль, и файлы так и лежат, пока вы этим не займётесь.',
  'notifications.event.captchaWaiting': 'Капча ждёт',
  'notifications.event.captchaWaitingHint': 'Окно капчи в этой вкладке открывается в любом случае. Изначально стоит «Ничего не показывать», потому что, пока вы смотрите на экран, это окно и есть сообщение. Поставьте «Системное уведомление», и капча из фоновой вкладки дойдёт до вас раньше, чем хостер выбросит сессию.',
  'notifications.event.captchaFailed': 'Капча не пройдена',
  'notifications.event.captchaFailedHint': 'Никто не ответил вовремя, или ответ не прошёл. Загрузка за ней так и стоит.',
  'notifications.event.captchaResolved': 'На капчу ответили в другом месте',
