  'notifications.systemUnavailable': 'Системных уведомлений здесь нет: ваш браузер предлагает их только по HTTPS или на localhost. Всё с этой карточки по-прежнему показывается в приложении.',
  'notifications.systemBlocked': 'Ваш браузер блокирует уведомления для этого адреса. Строки, стоящие на «Системном уведомлении», показываются вместо этого в приложении, пока вы снова не разрешите их в настройках сайта в браузере.',
  'notifications.systemNotGranted': 'Браузер не дал разрешения, поэтому это событие остаётся в приложении. Выберите «Системное уведомление» ещё раз, чтобы спросить снова.',
