  'volume.split.backend': 'По бэкендам',
  'volume.other': 'Всё остальное',
  'volume.empty': 'За этот период ещё ничего не завершилось.',
  'volume.unsizedHint': 'У {n} из этих загрузок хостер так и не назвал размер. К сумме они ничего не добавляют, поэтому настоящее значение выше нарисованного.',
  'volume.trimmedHint': 'История дошла до собственного предела, поэтому всё, что старше её самой ранней записи, отсутствует и в этой кривой. Увеличьте на этой странице число записей в истории, если хотите видеть дальше назад.',
  'volume.meter': 'Объём',
  'volume.meterHint': 'Что было загружено до конца с последнего обнуления счётчика, измеренное по лимиту со страницы настроек «Загрузки». Число сдвигается, когда загрузка завершается, а не пока она идёт: оно скачет, а не ползёт. Оно складывается из истории загрузок, поэтому тот, кто очистит историю, обнулит заодно и этот счётчик.',
