  'commands.openEvents': 'Открыть список событий',
  'list.keysHint': 'Списком можно управлять с клавиатуры. Tab заводит в него, клавиши со стрелками ведут от строки к строке, пробел добавляет строку к выбору или убирает её оттуда, Shift со стрелкой берёт сразу целый участок, Enter открывает свойства, а стрелки влево и вправо сворачивают и разворачивают пакет. В разделе Настройки, Горячие клавиши перечислены все.',
  'settings.shortcuts.listTitle': 'Клавиши списка',
