  'settings.diagnostics.fileCurrent': 'Текущий файл',
  'settings.diagnostics.fileOlder': 'Старый файл {n}',
  'settings.diagnostics.fileEmpty': 'Пока ничего не записано.',
  'settings.diagnostics.fileDownload': 'Скачать',
  'settings.diagnostics.logSearch': 'Искать по строкам',
  'settings.diagnostics.logSearchHint': 'Обычный текст, без подстановочных знаков, регистр не важен. Ищет по загруженным здесь строкам, а не по старым файлам. Чтобы искать по всему файлу целиком, скачайте его.',
  'settings.diagnostics.logSource': 'Источник',
  'settings.diagnostics.logSourceAll': 'Все источники',
  'settings.diagnostics.logSourceOther': 'Остальные строки',
  'settings.diagnostics.logSourceHint': 'Из какой части приложения пришла строка, прочитано по самому её началу. Строка, которая не называет никакой части, попадает в «Остальные строки». Фильтровать по уровню важности нельзя: в этом приложении его не записывает никто.',
  'settings.diagnostics.logFollow': 'Следовать за новыми строками',
