  'settings.diagnostics.fix.missing': 'Папки нет. Ближайшая существующая над ней, это {measured}. На машине, где примонтирован общий ресурс, это обычно значит, что ресурс не примонтирован, и здесь намеренно ничего не создавали: папка, созданная под отсутствующим монтированием, примет загрузки на себя, и при следующем обновлении контейнера они пропадут.',
  'settings.diagnostics.fix.denied': 'Папка есть, а писать в неё этот экземпляр не может. В контейнере KnightLoader работает как uid 1000, поэтому папка должна принадлежать этому пользователю или группе, в которой он состоит.',
  'settings.diagnostics.fix.readonly': 'Файловая система под этой папкой примонтирована только для чтения. Этот экземпляр ничем этого не изменит, менять нужно монтирование.',
  'settings.diagnostics.fix.full': 'На томе, где лежит эта папка, места больше нет.',
  'settings.diagnostics.fix.notRemoved': 'Тестовый файл удалось записать и не удалось удалить обратно. Загрузка пришла бы сюда, и потом её никогда бы не переименовали и не убрали с дороги. Посмотрите на право удаления у папки, а не на право записи.',
  'settings.diagnostics.fix.notADir': 'По этому пути лежит файл, а не папка.',
  'settings.diagnostics.fix.timeout': 'Папка не ответила вовремя и была оставлена в покое. Общий ресурс, сервер которого выключен, ведёт себя ровно так же, и такой же в пропавшей сети тоже.',
  'settings.diagnostics.fix.dataDenied': 'Это та единственная папка, без которой экземпляр не обходится: здесь лежат база данных, настройки и зашифрованное хранилище аккаунтов. Загрузки пока продолжают идти, а следующее сохранение пропадёт.',
  'settings.diagnostics.fix.javaMissing': 'Java не найдена. Образ контейнера приносит её с собой, десктопная установка берёт встроенную среду выполнения или ту, что в PATH. Без неё закрытый JDownloader не стартует, а значит зашифрованную ссылку-контейнер (.dlc, .ccf, .rsdf) вообще не открыть. Задайте JAVA_HOME, или направьте KL_JD на JDownloader, который работает где-то ещё.',
  'settings.diagnostics.fix.javaNotNeeded': 'Этот экземпляр не запускает собственного процесса Java: либо KL_JD указывает на JDownloader, который работает где-то ещё, либо закрытый выключен через KL_PROVISION_JD=0.',
  'settings.diagnostics.fix.ytdlpMissing': 'yt-dlp не найден (KL_YTDLP или «yt-dlp» в PATH). Медиастраницы после этого падают с ошибкой самого сайта, вместо того чтобы скачиваться.',
  'settings.diagnostics.fix.ffmpegMissing': 'ffmpeg не найден. Он нужен yt-dlp, чтобы сводить раздельные дорожки изображения и звука, которые отдаёт большинство сайтов, поэтому загрузка либо останавливается на одной из двух, либо возвращается без звука.',
  'settings.diagnostics.fix.ffprobeMissing': 'ffprobe не найден. Его использует только проверка длительности готового видео, всё остальное работает и без него.',
  'settings.diagnostics.fix.notRunnable': 'Найдено по пути {subject}, но не запустилось: {error}',
  'settings.diagnostics.fix.appearedLate': 'Сейчас он работает, а при запуске этого экземпляра его не было, поэтому к нему пока ничего не направляют. Перезапустите, чтобы он был подхвачен.',
  'settings.diagnostics.fix.utcFallback': 'TZ стоит на {subject}, а этот экземпляр эту зону загрузить не смог и молча откатился к UTC. Пока это не исправлено, каждое окно расписания идёт по UTC. Сверьте написание со списком зон («Europe/Berlin») и заодно то, есть ли в образе база часовых поясов вообще.',
  'settings.diagnostics.fix.noZoneDatabase': 'На этой системе нет базы часовых поясов, поэтому время читают вообще без переходов на летнее время. Ночное окно сохраняет свой зимний час всё лето, и никто не скажет, когда это случится.',
  'settings.diagnostics.fix.tzUnset': 'TZ не задана и местное время не найдено, поэтому этот экземпляр работает по UTC. Это работает, и об этом стоит знать: окно расписания, записанное как 23:00, значит 23:00 UTC, а не 23:00 у вас.',
  'settings.resolvers.toolsTitle': 'Инструменты',
  'settings.resolvers.toolsHint': 'yt-dlp читает медиастраницу, ffmpeg сводит дорожки, которые она отдаёт. И то и другое, это отдельные программы, которые запускает KnightLoader, и ни одна из них не входит в эту сборку, поэтому их версии стоит знать: устаревший yt-dlp, это самая частая причина, по которой ссылка на медиастраницу, работавшая в прошлом месяце, работать перестаёт.',
