  'settings.resolvers.toolsFrom.path': 'Найден в PATH',
  'settings.resolvers.toolsFrom.none': 'Нигде',
  'settings.resolvers.toolsYtdlpMissingHint': 'Без yt-dlp медиабэкенда нет вообще: ссылка на страницу с видео отклоняется с собственной ошибкой сайта, вместо того чтобы скачаться. В контейнере он приходит из пакета yt-dlp в образе, на десктопе вы ставите его сами и либо кладёте в PATH, либо направляете на него KL_YTDLP. Кнопка ниже сама принесёт копию, если ни то, ни другое не годится.',
  'settings.resolvers.toolsFfmpegMissingHint': 'Без ffmpeg yt-dlp не может свести раздельные дорожки изображения и звука, которые отдаёт большинство сайтов, поэтому загрузка либо ложится немой видеодорожкой, либо срывается совсем. Без ffprobe «Проверка готового файла» выше на этой странице ничего не измеряет и ничего об этом не говорит. В контейнере оба приходят из пакета ffmpeg, который ставит образ, на десктопе вы ставите их сами и кладёте в PATH.',
  'settings.resolvers.toolsShadowed': 'Работает собственная копия KnightLoader. Пока она здесь, ни KL_YTDLP, ни PATH не запускаются: вместо неё пошёл бы {path}, и он сообщает {version}.',
  'settings.resolvers.toolsShadowedOlder': 'Осторожно: копия, которую принёс KnightLoader ({current}), старше той, что и так лежит на этой машине ({system}, по пути {path}). Обновление контейнера приносит с собой более новый yt-dlp, а ваша собственная копия с ним не едет. Принесите новую, или вернитесь к системной копии.',
  'settings.resolvers.toolsManagedBroken': 'По пути {path} записана принесённая копия, и она не запускается. Вместо неё работает запасной вариант, показанный выше. Принесите её заново, или вернитесь к системной копии.',
  'settings.resolvers.toolsActions': 'Как держать yt-dlp свежим',
  'settings.resolvers.toolsActionsHint': 'При загрузке yt-dlp забирают с github.com, сверяют с файлом SHA2-256SUMS, опубликованным в том же релизе, один раз запускают, чтобы увидеть, что он на этой машине вообще работает, и только после этого кладут рядом с вашими данными, откуда его и запускает KnightLoader. До этого последнего шага продолжает работать та копия, что у вас уже была, а yt-dlp вашей системы не трогают никогда.',
